public boolean validTree(int n, int[][] edges) {
    if (edges.length != n - 1) return false;
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    boolean[] visited = new boolean[n];
    if (hasCycle(adj, visited, 0, -1)) return false;
    for (boolean v : visited) {
        if (!v) return false; // disconnected
    }
    return true;
}

private boolean hasCycle(List<List<Integer>> adj, boolean[] visited,
                         int node, int parent) {
    visited[node] = true;
    for (int nb : adj.get(node)) {
        if (nb == parent) continue;        // the edge we came in on
        if (visited[nb]) return true;      // revisit of non-parent → cycle
        if (hasCycle(adj, visited, nb, node)) return true;
    }
    return false;
}

