def validTree(self, n: int, edges: list[list[int]]) -> bool:
    if len(edges) != n - 1:
        return False
    adj: list[list[int]] = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    visited = [False] * n

    def has_cycle(node: int, parent: int) -> bool:
        visited[node] = True
        for nb in adj[node]:
            if nb == parent:
                continue              # the edge we arrived on
            if visited[nb]:
                return True           # non-parent revisit → cycle
            if has_cycle(nb, node):
                return True
        return False

    if has_cycle(0, -1):
        return False
    return all(visited)  # connectivity check

